import Foundation
import XCTest
@testable import JyotishCore

final class AnnualTests: XCTestCase {
    private func date(_ iso: String) throws -> Date {
        try XCTUnwrap(ISO8601DateFormatter().date(from: iso))
    }

    func testTwentySahamsMatchIndependentPythonDayAndNightFixtures() throws {
        // Generated by the unchanged core.sahams.compute_sahams, with synthetic positions.
        let values: [Double] = [10, 123, 214, 340, 287, 56, 178, 320, 140]
        let names = ["Sunce", "Mjesec", "Mars", "Merkur", "Jupiter", "Venera", "Saturn", "Rahu", "Ketu"]
        let positions = Dictionary(uniqueKeysWithValues: zip(names, values).map { ($0.0, PlanetPosition(name: $0.0, longitude: $0.1, speed: 1)) })
        let day: [String: Double] = ["Artha":144,"Bandhu":294,"Bhratri":186,"Karma":281,"Labha":137,"Matri":144,"Mitra":213,"Paradesa":186,"Pitri":215,"Preeti":6,"Punya":160,"Putra":241,"Rajya":215,"Roga":331,"Sastra":119,"Sraddha":249,"Vidya":324,"Vivaha":285,"Vyapara":113,"Yasha":204]
        let night: [String: Double] = ["Artha":144,"Bandhu":190,"Bhratri":186,"Karma":203,"Labha":137,"Matri":340,"Mitra":123,"Paradesa":186,"Pitri":269,"Preeti":170,"Punya":324,"Putra":241,"Rajya":269,"Roga":123,"Sastra":231,"Sraddha":235,"Vidya":160,"Vivaha":285,"Vyapara":113,"Yasha":114]
        XCTAssertEqual(try Sahams.calculate(ascendant: 47, positions: positions, isDay: true), day)
        XCTAssertEqual(try Sahams.calculate(ascendant: 47, positions: positions, isDay: false), night)
        XCTAssertThrowsError(try Sahams.calculate(ascendant: 47, positions: [:], isDay: true))
    }

    func testAnnualReferenceAndMuddaCoverWholeSolarYear() throws {
        let birth = try date("1985-11-04T00:15:00Z")
        let annual = try Annual.calculate(birthDate: birth, latitude: 45.45, longitude: 16.3667, year: 2026)
        XCTAssertEqual(annual.chart.ascendantSign, 9) // Jarac, unchanged Python fixture.
        XCTAssertEqual(annual.munthaSignIndex, 9)
        XCTAssertEqual(annual.completedYears, 41)
        XCTAssertEqual(annual.lifeYear, 42)
        XCTAssertEqual(annual.sahams.count, 20)
        XCTAssertEqual(annual.varsheshwara.winner?.planet, "Mars")
        XCTAssertEqual(annual.muddaDasha.first?.start, annual.returnDate)
        XCTAssertEqual(annual.muddaDasha.last?.end, annual.nextReturnDate)
        for (a, b) in zip(annual.muddaDasha, annual.muddaDasha.dropFirst()) { XCTAssertEqual(a.end, b.start) }
        let natal = try Ephemeris.chart(date: birth, latitude: 45.45, longitude: 16.3667)
        let longitude = try Ephemeris.sunLongitude(julianDay: annual.chart.julianDay)
        XCTAssertLessThan(abs(Astro.signedDifference(longitude - natal.positions["Sunce"]!.longitude)), 1e-6)
    }

    func testAllTwelveMasaEntriesFindThirtyDegreeSolarSteps() throws {
        let birth = try date("1985-11-04T00:15:00Z")
        let natal = try Ephemeris.chart(date: birth, latitude: 45.45, longitude: 16.3667)
        let sun = try XCTUnwrap(natal.positions["Sunce"]?.longitude)
        let annual = try Annual.calculate(birthDate: birth, latitude: 45.45, longitude: 16.3667, year: 2026)
        let months = try Annual.masa(natalSunLongitude: sun, annualJulianDay: annual.chart.julianDay, latitude: 45.45, longitude: 16.3667)
        XCTAssertEqual(months.count, 12)
        XCTAssertEqual(months.first?.returnDate, annual.returnDate)
        for (index, month) in months.enumerated() {
            XCTAssertEqual(month.monthNumber, index + 1)
            let result = try Ephemeris.sunLongitude(julianDay: month.chart.julianDay)
            XCTAssertLessThan(abs(Astro.signedDifference(result - sun - Double(index) * 30)), 1e-6)
            XCTAssertEqual(month.chart.positions.count, 9)
            if index > 0 { XCTAssertGreaterThan(month.returnDate, months[index - 1].returnDate) }
        }
    }

    func testLateMonthReturnRepairsConfirmedPythonUnbracketedSearch() throws {
        let birth = try date("1985-01-31T12:00:00Z")
        let sun = try Ephemeris.sunLongitude(julianDay: Ephemeris.julianDay(date: birth))
        let jd = try Annual.solarReturn(natalSunLongitude: sun, targetYear: 2026, birthMonth: 1, birthDay: 31)
        // Legacy returns Jan31 12:00 at its search boundary, 0.528868° short of target.
        // The verified root is Feb1 00:30:30.995... UTC using the original Moshier ephemeris.
        XCTAssertGreaterThan(jd, 2461072.0)
        XCTAssertLessThan(abs(Astro.signedDifference(try Ephemeris.sunLongitude(julianDay: jd) - sun)), 1e-6)
    }

    func testBirthCalendarYearUsesExplicitLocalTimeZone() throws {
        // Absolute instant is Dec31 UTC, but original Python person's birth_date is Jan1 in Zagreb.
        let birth = try date("1999-12-31T23:15:00Z")
        let zone = try XCTUnwrap(TimeZone(identifier: "Europe/Zagreb"))
        let result = try Annual.calculate(birthDate: birth, latitude: 45.45, longitude: 16.3667, year: 2026, birthTimeZone: zone)
        XCTAssertEqual(result.completedYears, 26)
        XCTAssertEqual(result.lifeYear, 27)
    }

    func testActiveYearAndInvalidAnnualRange() throws {
        let birth = try date("1985-11-04T00:15:00Z")
        XCTAssertEqual(try Annual.activeYear(birthDate: birth, latitude: 45.45, longitude: 16.3667, referenceDate: date("2026-01-01T00:00:00Z")), 2025)
        XCTAssertThrowsError(try Annual.calculate(birthDate: birth, latitude: 45.45, longitude: 16.3667, year: 1984))
        XCTAssertThrowsError(try Annual.calculate(birthDate: birth, latitude: 45.45, longitude: 16.3667, year: 2399))
        XCTAssertThrowsError(try Annual.solarReturn(natalSunLongitude: .nan, targetYear: 2026, birthMonth: 1, birthDay: 1))
    }
}
